/// Parses a prefix operator, if there is one and its precedence is at least
/// min_precedence.
fn parse_prefix_operator_at(&mut self, min_precedence: Precedence) -> Option<PrefixOperator> {
    if self.next_is(Token::Minus) {
        Some(PrefixOperator::Negate)
    } else if self.next_is(Token::Keyword(Keyword::Not)) {
        Some(PrefixOperator::Not)
    } else if self.next_is(Token::Plus) {
        Some(PrefixOperator::Identity)
    } else {
        None
    }
}
